update pages set contenu = '{"sections":[]}'::jsonb where path = '/travaux-industriels/demantelement-industriel/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Démantèlement industriel","mecanisme":"**Une zone rendue libre, propre et documentée.** Pas un tas de ferraille et trois bennes non tracées.","cta":"Faire chiffrer mon démantèlement","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30"},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs · techniciens salariés Migen, pas de chaîne d''intermédiaires."},{"valeur":"+ 120","libelle":"clients industriels · dont plus de 80 qui reviennent chaque année."},{"valeur":"4","libelle":"agences · Lyon (siège), Montréal, Dubaï, Madrid, et des hubs techniques en France."},{"valeur":"10 %","libelle":"des candidats retenus · entretien technique et entretien comportemental, résultats partagés avec vous."}]},{"type":"probleme","punchline":"Un démantèlement mal fait se paie deux fois : à l''enlèvement, puis à la remise des clés.","puces":[{"accroche":"Des énergies coupées au mauvais endroit.","texte":"Une ligne voisine encore en production s''arrête avec celle qu''on démonte."},{"accroche":"Un équipement destiné au transfert démonté comme de la ferraille.","texte":"Il part en morceaux, il arrive inutilisable."},{"accroche":"Aucune traçabilité des déchets.","texte":"Le jour du contrôle, il manque la moitié des bordereaux."},{"accroche":"La valorisation oubliée.","texte":"Moteurs, variateurs et pièces inox partent au prix de la benne mixte."}]},{"type":"offre","lignes":[{"prestation":{"texte":"**Préparation et sécurisation des zones**"},"benefice":"Balisage, consignation des énergies, isolement des lignes voisines, plan de prévention. La production qui continue n''est pas touchée."},{"prestation":{"texte":"**Vidanges et purges avant dépose**"},"benefice":"Huiles, fluides hydrauliques, fluides caloporteurs, circuits pneumatiques et hydrauliques mis à zéro. Rien ne s''écoule pendant le levage."},{"prestation":{"texte":"**Repérage préalable des installations**"},"benefice":"Câblage, tuyauterie, points d''ancrage et points d''élingage relevés avant de toucher quoi que ce soit. C''est ce repérage qui rend un remontage possible."},{"prestation":{"texte":"**Démontage avec repérage pour transfert**"},"benefice":"L''équipement est démonté pour repartir, pas pour disparaître. Il rejoint un [transfert industriel](/travaux-industriels/transfert-industriel/) ou un stockage."},{"prestation":{"texte":"**Démontage pour valorisation**"},"benefice":"Sous-ensembles, moteurs, armoires, inox et métaux triés à la dépose plutôt qu''au sol. Ce qui a de la valeur est mis de côté avant de la perdre."},{"prestation":{"texte":"**Dépose de réseaux et d''utilités**"},"benefice":"Alimentations électriques, air comprimé, vapeur, eau, aéraulique. Les arrivées sont proprement obturées et repérées sur plan."},{"prestation":{"texte":"**Découpe et évacuation**"},"benefice":"Découpe des charpentes et des structures support, sortie par les accès réels du bâtiment, évacuation coordonnée."},{"prestation":{"texte":"**Tri et traçabilité des déchets**"},"benefice":"Tri par filière, bordereaux de suivi, pesées. Vous recevez le dossier qui prouve où chaque tonne est allée."},{"prestation":{"texte":"**Remise en état de la zone**"},"benefice":"Scellements arasés, sols nettoyés, points d''ancrage traités. La surface est rendue exploitable pour la suite."},{"prestation":{"texte":"**Dossier de fin de chantier**"},"benefice":"Plans à jour, repérages, photos, bordereaux. Vous rendez les clés avec une pièce, pas une promesse."}]},{"type":"deroule","etapes":[{"titre":"Visite et inventaire.","texte":"Équipement par équipement, ce qui part pour être réutilisé, ce qui part pour être valorisé, ce qui part en déchet. La décision est prise avec vous, avant le devis."},{"titre":"Analyse de risque et plan de prévention.","texte":"Coactivité avec votre production, accès, levage, découpe, points chauds. Écrit, signé, affiché."},{"titre":"Consignation et mise en sécurité.","texte":"Énergies coupées, condamnées, vérifiées. Fluides vidangés et évacués par les filières adaptées."},{"titre":"Dépose selon la destination.","texte":"Repérage complet pour ce qui sera remonté, démontage direct pour ce qui sera valorisé. Les deux gestes ne se ressemblent pas."},{"titre":"Évacuation et traçabilité.","texte":"Sortie des charges, chargement, bordereaux de suivi, pesées par filière."},{"titre":"Remise en état et restitution.","texte":"Nettoyage, reprise des points d''ancrage, dossier de fin de chantier remis à votre exploitant."}]},{"type":"garanties","puces":[{"accroche":"La production voisine ne s''arrête pas à cause du démantèlement.","texte":"La coactivité est traitée avant le premier balisage, pas découverte le premier matin."},{"accroche":"Ce qui doit repartir repart démontable.","texte":"Un équipement destiné au transfert est déposé avec repérage complet, sauvegarde des programmes et conditionnement."},{"accroche":"Chaque déchet a un bordereau.","texte":"Tri par filière, pesées, traçabilité remise en fin de chantier. Vous êtes en mesure de répondre à un contrôle."}]},{"type":"cta","question":"Besoin de libérer une zone, un atelier ou un site entier ?","bouton":"Faire chiffrer mon démantèlement","href":"/contact/","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/travaux-industriels/demantelement-industriel/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Montage et déplacement de machines, étanchéité et isolation, 2025.","texte":"Transferts de machines sécurisés, sans casse ni improvisation, délais de chantier tenus","lienLibelle":"Étude de cas SOPREMA","lienHref":"/preuves/soprema/"},{"titre":"Montage d''un centre logistique, Clermont-Ferrand, 2023.","texte":"12 monteurs mécaniciens et 8 engins de levage mobilisés, site livré à la date prévue","lienLibelle":"Étude de cas AKTID","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Construction d''un site de R&D bas carbone, région parisienne.","texte":"Pilotage de chantier de bout en bout par Orthus, filiale du groupe, coordination multi-métiers","lienLibelle":"Étude de cas ORTHUS x ECOCEM","lienHref":"/preuves/orthus-ecocem/"},{"titre":"Contrôle de chantier, projets stratégiques, 2025 à 2026.","texte":"Suivi des prestataires, vérification des installations, respect des procédures","lienLibelle":"Étude de cas ALSTEF Group","lienHref":"/preuves/alstef-group/"}]},{"type":"objections","questions":[{"question":"Combien coûte un démantèlement industriel ?","reponse":"Le montant dépend du volume d''équipements, des contraintes d''accès, de la part de valorisation et du niveau de remise en état attendu. Chiffrage sur devis après visite, poste par poste. La valeur des matières récupérables apparaît sur une ligne du devis, elle n''y est pas noyée."},{"question":"Intervenez-vous pendant que le site produit encore ?","reponse":"Oui, c''est le cas le plus fréquent. La zone démantelée est isolée du reste, les énergies communes sont identifiées avant toute coupure, et le plan de prévention encadre la coactivité."},{"question":"Faites-vous du démantèlement nucléaire ?","reponse":"Non. Notre périmètre est le démantèlement industriel d''équipements et d''installations de production. Le nucléaire, le naval et la déconstruction de bâtiment relèvent d''autres métiers et d''autres agréments."},{"question":"Que devient un équipement encore en bon état ?","reponse":"Trois issues possibles, décidées avec vous à l''inventaire : remonté ailleurs dans le cadre d''un transfert, stocké en pièces de rechange, ou cédé pour valorisation. Le mode de démontage change selon l''issue retenue."},{"question":"Qui gère les déchets et les bordereaux ?","reponse":"Nous, avec les filières adaptées à chaque flux. Vous recevez le dossier de traçabilité en fin de chantier : tri par filière, pesées, bordereaux de suivi."},{"question":"Qui sont les techniciens qui interviennent ?","reponse":"Des salariés Migen, évalués en entretien technique et en entretien comportemental. Seuls 10 % des candidats sont retenus. Mécanique, électricité, hydraulique, pneumatique, soudure et chaudronnerie."}]},{"type":"ctaFinal","question":"Besoin d''un inventaire avant de décider ce qui part et ce qui reste ?","bouton":"Parler à un chargé d''affaires","href":"/contact/","rappel":"04 78 33 72 05, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/travaux-industriels/demantelement-industriel/';
